import ExampleSupport
import SwiftUI

@main struct DemoApp: App {
    public var body: some Scene {
        WindowGroup {
            ContentView()
        }
    }
}

private struct ContentView: View {
    var body: some View {
        Text(generatedGreeting)
            .padding()
            .task {
                do {
                    try verify()
                    Example.pass()
                } catch {
                    print("Test failed: \(error)")
                    exit(1)
                }
            }
    }
}

private func verify() throws {
    // generated by GreetingPlugin from Greeting.txt
    let expected = "Hello from a build tool plugin"
    guard generatedGreeting == expected else {
        throw StringError("Expected greeting \(String(reflecting: expected)), got \(String(reflecting: generatedGreeting))")
    }
}
